import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"用量与额度","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/usage.md","filePath":"guide/agent/usage.md","lastUpdated":1789295632000}'),s={name:"guide/agent/usage.md"};function n(l,a,i,d,g,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="用量与额度" tabindex="-1">用量与额度 <a class="header-anchor" href="#用量与额度" aria-label="Permalink to &quot;用量与额度&quot;">​</a></h1><p>智能体的对话、生图、识图、便签压缩都消耗<strong>额度</strong>。在「我的用量」页面管理一切和额度有关的事。</p><h2 id="额度从哪来" tabindex="-1">额度从哪来 <a class="header-anchor" href="#额度从哪来" aria-label="Permalink to &quot;额度从哪来&quot;">​</a></h2><ul><li><strong>每日签到</strong>：每天签到可以领取额度。奖励有随机成分（「今日手气」），连续签到有加成，特定身份组有额外倍率，节日可能有活动加成。</li><li><strong>卡密兑换</strong>：管理员发放的充值卡密，在「我的用量」页输入即可兑换。</li><li><strong>管理员签发</strong>：活动奖励等由管理员直接发放。</li></ul><h2 id="费用怎么算" tabindex="-1">费用怎么算 <a class="header-anchor" href="#费用怎么算" aria-label="Permalink to &quot;费用怎么算&quot;">​</a></h2><ul><li><strong>对话</strong>：按模型每张卡片标注的单次费用计费。不同模型价格不同，切换模型即切换单价。</li><li><strong>生图</strong>：按所选生图模型的「每张费用」计费。</li><li><strong>识图</strong>：发送图片触发识图时按次计费。</li><li><strong>便签压缩</strong>：为会话单独选择压缩模型时，摘要按该模型单独计费，与主回复分开扣（时机可能略有先后）。</li></ul><p>发送前，「模型」标签页会显示<strong>预计单次发送费用</strong>，卡片上标注「免费」的模型不扣额度。</p><h2 id="用量记录" tabindex="-1">用量记录 <a class="header-anchor" href="#用量记录" aria-label="Permalink to &quot;用量记录&quot;">​</a></h2><p>「我的用量」列出每次调用记录：模型、费用、状态，方便对账。失败的请求<strong>不计费</strong>。</p><h2 id="余额不足" tabindex="-1">余额不足 <a class="header-anchor" href="#余额不足" aria-label="Permalink to &quot;余额不足&quot;">​</a></h2><p>提示「智能体对话余额不足，无法发送」时，去签到或兑换卡密。生图遇到「额度不足」同理。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>想在额度内玩得更久：把长对话交给便签压缩（减少重复发送原文的开销），或切换到费用更低的模型聊日常，重要剧情再切高质量模型。</p></div>',12)])])}const p=t(s,[["render",n]]);export{h as __pageData,p as default};
